    .stat h3 { font-size: 2rem; color: #256DEB; margin-bottom: 5px; }
    .stat p { color: #666; font-size: 0.9rem; }

    .section-title { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
    .section-title h2 { color: #333; }

    .bookings-list { display: flex; flex-direction: column; gap: 10px; }
    .booking-item { display: flex; justify-content: space-between; align-items: center; padding: 15px; background: white; border-radius: 8px; }
    .booking-info h4 { margin-bottom: 5px; }
    .booking-info span { color: #666; font-size: 0.9rem; }
    .booking-meta { text-align: right; }
    .booking-meta .date { font-weight: 600; }
    .booking-meta .time { color: #256DEB; }
    .booking-meta .service { font-size: 0.85rem; color: #666; }

    .service-form { display: flex; flex-direction: column; gap: 10px; }
    .service-row { display: grid; grid-template-columns: 2fr 1fr 1fr auto; gap: 10px; align-items: end; }
    .service-row input { padding: 10px; border: 2px solid #eee; border-radius: 8px; }

    .tabs { display: flex; gap: 10px; margin-bottom: 20px; }
    .tab { padding: 10px 20px; background: white; border: none; border-radius: 8px; cursor: pointer; }
    .tab.active { background: #256DEB; color: white; }

    .tab-content { display: none; }
    .tab-content.active { display: block; }

    .hidden { display: none !important; }
