<body>
  <!-- Login -->
  <div class="login-screen" id="loginScreen">
    <h1>EeziBook Admin</h1>
    <div class="card">
      <div class="form-group">
        <label>Email</label>
        <input type="email" id="email" value="demo@eezibook.com">
