            <h4>Add New Service</h4>
            <div class="service-row">
              <input type="text" id="newServiceName" placeholder="Service name">
              <input type="number" id="newServiceDuration" placeholder="Minutes">
              <input type="number" id="newServicePrice" placeholder="Price (R)">
              <button class="btn" onclick="addService()">Add</button>
