  <script>
    let businessId = null;

    async function login() {
      console.log('Login clicked');
      const email = document.getElementById('email').value;
      const password = document.getElementById('password').value;

      console.log('Attempting login with:', email);

      try {
        const res = await fetch('/api/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email, password })
        });

        console.log('Response status:', res.status);

        if (res.ok) {
          const business = await res.json();
          console.log('Login successful, business:', business);
          businessId = business.id;

          // Hide login, show dashboard
          document.getElementById('loginScreen').style.display = 'none';
          document.getElementById('dashboard').style.display = 'block';

          loadDashboard();
        } else {
          const error = await res.json();
          console.error('Login failed:', error);
          alert('Invalid credentials: ' + (error.message || 'Please try again'));
        }
      } catch (err) {
        console.error('Login error:', err);
        alert('Login error: ' + err.message);
      }
    }

    function logout() {
      businessId = null;
      document.getElementById('loginScreen').style.display = 'block';
      document.getElementById('dashboard').style.display = 'none';
    }

    async function loadDashboard() {
      loadBookings();
      loadServices();
    }

    async function loadBookings() {
      const res = await fetch(`/api/bookings/${businessId}`);
      const bookings = await res.json();

      const today = new Date();
      const todayStr = today.toISOString().split('T')[0];

      // This week's start (Monday) and end (Sunday)
      const thisWeekStart = new Date(today);
      thisWeekStart.setDate(today.getDate() - (today.getDay() - 1));
      const thisWeekEnd = new Date(thisWeekStart);
      thisWeekEnd.setDate(thisWeekStart.getDate() + 6);

      // Next week's start (Monday) and end (Sunday)
      const nextWeekStart = new Date(thisWeekStart);
      nextWeekStart.setDate(thisWeekStart.getDate() + 7);
      const nextWeekEnd = new Date(nextWeekStart);
      nextWeekEnd.setDate(nextWeekStart.getDate() + 6);

      // Last week's start and end
      const lastWeekStart = new Date(thisWeekStart);
      lastWeekStart.setDate(lastWeekStart.getDate() - 7);
      const lastWeekEnd = new Date(lastWeekStart);
      lastWeekEnd.setDate(lastWeekStart.getDate() + 6);

      // Calculate appointment counts
      const todayCount = bookings.filter(b => b.booking_date === todayStr).length;
      const thisWeekCount = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= thisWeekStart && d <= thisWeekEnd;
      }).length;
      const nextWeekCount = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= nextWeekStart && d <= nextWeekEnd;
      }).length;

      document.getElementById('todayCount').textContent = todayCount;
      document.getElementById('weekCount').textContent = thisWeekCount;
      document.getElementById('nextWeekCount').textContent = nextWeekCount;

      // Calculate revenue
      const thisMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
      const lastMonthStart = new Date(today.getFullYear(), today.getMonth() - 1, 1);
      const lastMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0);

      const revenueThisWeek = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= thisWeekStart && d <= thisWeekEnd;
      }).reduce((sum, b) => sum + (b.service_price || 0), 0);

      const revenueLastWeek = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= lastWeekStart && d <= lastWeekEnd;
      }).reduce((sum, b) => sum + (b.service_price || 0), 0);

      const revenueThisMonth = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= thisMonthStart;
      }).reduce((sum, b) => sum + (b.service_price || 0), 0);

      const revenueLastMonth = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= lastMonthStart && d <= lastMonthEnd;
      }).reduce((sum, b) => sum + (b.service_price || 0), 0);

      document.getElementById('thisWeekRevenue').textContent = 'R' + revenueThisWeek;
      document.getElementById('lastWeekRevenue').textContent = 'R' + revenueLastWeek;
      document.getElementById('thisMonthRevenue').textContent = 'R' + revenueThisMonth;
      document.getElementById('lastMonthRevenue').textContent = 'R' + revenueLastMonth;

      // Filter bookings by time period
      const tomorrow = new Date(today);
      tomorrow.setDate(tomorrow.getDate() + 1);
      const tomorrowStr = tomorrow.toISOString().split('T')[0];

      // This week (Mon-Sun)
      const thisWeekStart = new Date(today);
      thisWeekStart.setDate(today.getDate() - (today.getDay() - 1));
      const thisWeekEnd = new Date(thisWeekStart);
      thisWeekEnd.setDate(thisWeekStart.getDate() + 6);

      // Next week
      const nextWeekStart = new Date(thisWeekStart);
      nextWeekStart.setDate(thisWeekStart.getDate() + 7);
      const nextWeekEnd = new Date(nextWeekStart);
      nextWeekEnd.setDate(nextWeekStart.getDate() + 6);

      // Next month
      const nextMonthStart = new Date(today.getFullYear(), today.getMonth() + 1, 1);
      const nextMonthEnd = new Date(today.getFullYear(), today.getMonth() + 2, 0);

      const bookingsToday = bookings.filter(b => b.booking_date === todayStr);
      const bookingsTomorrow = bookings.filter(b => b.booking_date === tomorrowStr);
      const bookingsThisWeek = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= thisWeekStart && d <= thisWeekEnd;
      });
      const bookingsNextWeek = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= nextWeekStart && d <= nextWeekEnd;
      });
      const bookingsNextMonth = bookings.filter(b => {
        const d = new Date(b.booking_date);
        return d >= nextMonthStart && d <= nextMonthEnd;
      });

      // Build collapsible sections
      const container = document.getElementById('bookingsList');
      container.innerHTML = '';

      const sections = [
        { title: "Today's Bookings", list: bookingsToday, dateStr: todayStr },
        { title: "Tomorrow's Bookings", list: bookingsTomorrow, dateStr: tomorrowStr },
        { title: "This Week's Bookings", list: bookingsThisWeek },
        { title: "Next Week's Bookings", list: bookingsNextWeek },
        { title: "Next Month's Bookings", list: bookingsNextMonth }
      ];

      sections.forEach((section, idx) => {
        const count = section.list.length;
        const sectionDiv = document.createElement('div');
        sectionDiv.className = 'section';
        sectionDiv.style.marginBottom = '12px';
        sectionDiv.innerHTML = `
          <div class="section-header" onclick="toggleBookingSection(this)" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center;padding:12px;background:#f5f5f5;border-radius:8px;">
            <span style="font-weight:600;">${section.title} (${count})</span>
            <span class="toggle-icon">▼</span>
          </div>
          <div class="section-content" style="padding:12px 0;">
            ${count === 0 ? '<p style="color:#666;text-align:center;">No bookings</p>' : ''}
          </div>
        `;
        container.appendChild(sectionDiv);

        const contentDiv = sectionDiv.querySelector('.section-content');
        section.list.forEach(b => {
          const div = document.createElement('div');
          div.className = 'booking-item';
          div.style.marginBottom = '8px';
          div.innerHTML = `
            <div style="display:flex;justify-content:space-between;align-items:center;">
              <div>
                <strong>${b.client_name}</strong><br>
                <span style="font-size:0.85rem;color:#666;">${b.client_phone} | ${b.client_email}</span>
              </div>
              <div style="text-align:right;">
                <div>${b.booking_date} at ${b.booking_time}</div>
                <div style="font-size:0.85rem;color:#256DEB;">${b.service_name} - R${b.service_price}</div>
              </div>
            </div>
          `;
          contentDiv.appendChild(div);
        });
      });
    }

    function toggleBookingSection(header) {
      const content = header.nextElementSibling;
      const icon = header.querySelector('.toggle-icon');
      content.classList.toggle('collapsed');
      icon.textContent = content.classList.contains('collapsed') ? '▶' : '▼';
    }

    async function loadServices() {
      const res = await fetch(`/api/services/${businessId}`);
      const services = await res.json();

      const container = document.getElementById('servicesList');
      container.innerHTML = '';

      services.forEach(s => {
        const div = document.createElement('div');
        div.className = 'service-row';
        div.style.marginBottom = '10px';
        div.innerHTML = `
          <span>${s.name}</span>
          <span>${s.duration} min</span>
          <span>R${s.price}</span>
          <button class="btn btn-danger" onclick="deleteService('${s.id}')">Delete</button>
        `;
        container.appendChild(div);
      });
    }

    async function addService() {
      const name = document.getElementById('newServiceName').value;
      const duration = parseInt(document.getElementById('newServiceDuration').value);
      const price = parseFloat(document.getElementById('newServicePrice').value);

      if (!name || !duration || !price) {
        alert('Please fill in all fields');
        return;
      }

      const res = await fetch('/api/services', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ business_id: businessId, name, duration, price })
      });

      if (res.ok) {
        document.getElementById('newServiceName').value = '';
        document.getElementById('newServiceDuration').value = '';
        document.getElementById('newServicePrice').value = '';
        loadServices();
      }
    }

    async function deleteService(id) {
      if (!confirm('Are you sure you want to delete this service?')) return;

      const res = await fetch(`/api/services/${id}`, { method: 'DELETE' });
      if (res.ok) loadServices();
    }

    function showTab(tab) {
      document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));

      event.target.classList.add('active');
      document.getElementById(`tab-${tab}`).classList.add('active');
    }
  </script>
</body>
</html>
